import{_ as t,a as o,o as a,a4 as r}from"./chunks/framework.-FZumj2l.js";const u=JSON.parse('{"title":"Reporting — Sales","description":"","frontmatter":{"outline":false,"apiType":"rest","examples":[{"id":"rest-sales-total-sales","title":"Total Sales","description":"Gross sales for the window vs. the previous period, plus an over-time series split into previous and current buckets. This is the default type.","query":"curl -X GET \\"https://your-domain.com/api/admin/reporting/sales?type=total-sales&start=2026-05-10&end=2026-06-09&channel=default\\" \\\\\\n  -H \\"Accept: application/json\\" \\\\\\n  -H \\"Authorization: Bearer <id>|<token>\\"\\n","response":"[\\n  {\\n    \\"entity\\": \\"sales\\",\\n    \\"type\\": \\"total-sales\\",\\n    \\"dateRange\\": { \\"previous\\": \\"10 Apr 2026 - 10 May 2026\\", \\"current\\": \\"10 May 2026 - 09 Jun 2026\\" },\\n    \\"statistics\\": {\\n      \\"sales\\": {\\n        \\"previous\\": 27243.5,\\n        \\"current\\": 9697.53,\\n        \\"formatted_total\\": \\"$9,697.53\\",\\n        \\"progress\\": -64.32\\n      },\\n      \\"over_time\\": {\\n        \\"previous\\": [\\n          { \\"label\\": \\"10 Apr\\", \\"total\\": 4200, \\"count\\": 6 },\\n          { \\"label\\": \\"11 Apr\\", \\"total\\": 1850.5, \\"count\\": 3 }\\n        ],\\n        \\"current\\": [\\n          { \\"label\\": \\"10 May\\", \\"total\\": 8500, \\"count\\": 12 },\\n          { \\"label\\": \\"11 May\\", \\"total\\": 1197.53, \\"count\\": 4 }\\n        ]\\n      }\\n    }\\n  }\\n]\\n"},{"id":"rest-sales-average-sales","title":"Average Sales","description":"Average order value for the window vs. the previous period, plus the previous/current over-time series.","query":"curl -X GET \\"https://your-domain.com/api/admin/reporting/sales?type=average-sales&start=2026-05-10&end=2026-06-09&channel=default\\" \\\\\\n  -H \\"Accept: application/json\\" \\\\\\n  -H \\"Authorization: Bearer <id>|<token>\\"\\n","response":"[\\n  {\\n    \\"entity\\": \\"sales\\",\\n    \\"type\\": \\"average-sales\\",\\n    \\"dateRange\\": { \\"previous\\": \\"10 Apr 2026 - 10 May 2026\\", \\"current\\": \\"10 May 2026 - 09 Jun 2026\\" },\\n    \\"statistics\\": {\\n      \\"sales\\": {\\n        \\"previous\\": 1135.15,\\n        \\"current\\": 606.1,\\n        \\"formatted_total\\": \\"$606.10\\",\\n        \\"progress\\": -46.61\\n      },\\n      \\"over_time\\": {\\n        \\"previous\\": [\\n          { \\"label\\": \\"10 Apr\\", \\"total\\": 700, \\"count\\": 6 },\\n          { \\"label\\": \\"11 Apr\\", \\"total\\": 616.83, \\"count\\": 3 }\\n        ],\\n        \\"current\\": [\\n          { \\"label\\": \\"10 May\\", \\"total\\": 708.33, \\"count\\": 12 },\\n          { \\"label\\": \\"11 May\\", \\"total\\": 299.38, \\"count\\": 4 }\\n        ]\\n      }\\n    }\\n  }\\n]\\n"},{"id":"rest-sales-total-orders","title":"Total Orders","description":"Order count for the window vs. the previous period, plus the previous/current over-time series.","query":"curl -X GET \\"https://your-domain.com/api/admin/reporting/sales?type=total-orders&start=2026-05-10&end=2026-06-09&channel=default\\" \\\\\\n  -H \\"Accept: application/json\\" \\\\\\n  -H \\"Authorization: Bearer <id>|<token>\\"\\n","response":"[\\n  {\\n    \\"entity\\": \\"sales\\",\\n    \\"type\\": \\"total-orders\\",\\n    \\"dateRange\\": { \\"previous\\": \\"10 Apr 2026 - 10 May 2026\\", \\"current\\": \\"10 May 2026 - 09 Jun 2026\\" },\\n    \\"statistics\\": {\\n      \\"orders\\": {\\n        \\"previous\\": 24,\\n        \\"current\\": 16,\\n        \\"progress\\": -33.33\\n      },\\n      \\"over_time\\": {\\n        \\"previous\\": [\\n          { \\"label\\": \\"10 Apr\\", \\"total\\": 4200, \\"count\\": 6 },\\n          { \\"label\\": \\"11 Apr\\", \\"total\\": 1850.5, \\"count\\": 3 }\\n        ],\\n        \\"current\\": [\\n          { \\"label\\": \\"10 May\\", \\"total\\": 8500, \\"count\\": 12 },\\n          { \\"label\\": \\"11 May\\", \\"total\\": 1197.53, \\"count\\": 4 }\\n        ]\\n      }\\n    }\\n  }\\n]\\n"},{"id":"rest-sales-purchase-funnel","title":"Purchase Funnel","description":"The four funnel stages — visitors, product visitors, carts, orders — each with a running total and progress. This type has no over-time series and is not available in table form.","query":"curl -X GET \\"https://your-domain.com/api/admin/reporting/sales?type=purchase-funnel&start=2026-05-10&end=2026-06-09&channel=default\\" \\\\\\n  -H \\"Accept: application/json\\" \\\\\\n  -H \\"Authorization: Bearer <id>|<token>\\"\\n","response":"[\\n  {\\n    \\"entity\\": \\"sales\\",\\n    \\"type\\": \\"purchase-funnel\\",\\n    \\"dateRange\\": { \\"previous\\": \\"10 Apr 2026 - 10 May 2026\\", \\"current\\": \\"10 May 2026 - 09 Jun 2026\\" },\\n    \\"statistics\\": {\\n      \\"visitors\\": { \\"total\\": 1820, \\"progress\\": 12.5 },\\n      \\"product_visitors\\": { \\"total\\": 940, \\"progress\\": 8.2 },\\n      \\"carts\\": { \\"total\\": 210, \\"progress\\": -4.1 },\\n      \\"orders\\": { \\"total\\": 16, \\"progress\\": -33.33 }\\n    }\\n  }\\n]\\n"},{"id":"rest-sales-abandoned-carts","title":"Abandoned Carts","description":"Abandoned-cart sales value, cart count and abandonment rate (each vs. the previous period), plus the products most often left in abandoned carts.","query":"curl -X GET \\"https://your-domain.com/api/admin/reporting/sales?type=abandoned-carts&start=2026-05-10&end=2026-06-09&channel=default\\" \\\\\\n  -H \\"Accept: application/json\\" \\\\\\n  -H \\"Authorization: Bearer <id>|<token>\\"\\n","response":"[\\n  {\\n    \\"entity\\": \\"sales\\",\\n    \\"type\\": \\"abandoned-carts\\",\\n    \\"dateRange\\": { \\"previous\\": \\"10 Apr 2026 - 10 May 2026\\", \\"current\\": \\"10 May 2026 - 09 Jun 2026\\" },\\n    \\"statistics\\": {\\n      \\"sales\\": {\\n        \\"previous\\": 8400,\\n        \\"current\\": 5210.75,\\n        \\"formatted_total\\": \\"$5,210.75\\",\\n        \\"progress\\": -37.97\\n      },\\n      \\"carts\\": {\\n        \\"previous\\": 38,\\n        \\"current\\": 27,\\n        \\"progress\\": -28.95\\n      },\\n      \\"rate\\": {\\n        \\"previous\\": 61.29,\\n        \\"current\\": 62.79,\\n        \\"progress\\": 2.45\\n      },\\n      \\"products\\": [\\n        { \\"id\\": 2359, \\"name\\": \\"Horizon Arc 49\\\\\\" OLED Curved Gaming Monitor\\", \\"count\\": 9, \\"progress\\": 12.5 },\\n        { \\"id\\": 1184, \\"name\\": \\"Aero Knit Running Shoes\\", \\"count\\": 6, \\"progress\\": -10 }\\n      ]\\n    }\\n  }\\n]\\n"},{"id":"rest-sales-refunds","title":"Refunds","description":"Refunded amount for the window vs. the previous period, plus the previous/current over-time series.","query":"curl -X GET \\"https://your-domain.com/api/admin/reporting/sales?type=refunds&start=2026-05-10&end=2026-06-09&channel=default\\" \\\\\\n  -H \\"Accept: application/json\\" \\\\\\n  -H \\"Authorization: Bearer <id>|<token>\\"\\n","response":"[\\n  {\\n    \\"entity\\": \\"sales\\",\\n    \\"type\\": \\"refunds\\",\\n    \\"dateRange\\": { \\"previous\\": \\"10 Apr 2026 - 10 May 2026\\", \\"current\\": \\"10 May 2026 - 09 Jun 2026\\" },\\n    \\"statistics\\": {\\n      \\"refunds\\": {\\n        \\"previous\\": 1420,\\n        \\"current\\": 730.5,\\n        \\"formatted_total\\": \\"$730.50\\",\\n        \\"progress\\": -48.56\\n      },\\n      \\"over_time\\": {\\n        \\"previous\\": [\\n          { \\"label\\": \\"10 Apr\\", \\"total\\": 620, \\"count\\": 2 },\\n          { \\"label\\": \\"11 Apr\\", \\"total\\": 800, \\"count\\": 3 }\\n        ],\\n        \\"current\\": [\\n          { \\"label\\": \\"10 May\\", \\"total\\": 430.5, \\"count\\": 1 },\\n          { \\"label\\": \\"11 May\\", \\"total\\": 300, \\"count\\": 1 }\\n        ]\\n      }\\n    }\\n  }\\n]\\n"},{"id":"rest-sales-tax-collected","title":"Tax Collected","description":"Tax collected for the window vs. the previous period, the top tax categories by collected amount, and the previous/current over-time series.","query":"curl -X GET \\"https://your-domain.com/api/admin/reporting/sales?type=tax-collected&start=2026-05-10&end=2026-06-09&channel=default\\" \\\\\\n  -H \\"Accept: application/json\\" \\\\\\n  -H \\"Authorization: Bearer <id>|<token>\\"\\n","response":"[\\n  {\\n    \\"entity\\": \\"sales\\",\\n    \\"type\\": \\"tax-collected\\",\\n    \\"dateRange\\": { \\"previous\\": \\"10 Apr 2026 - 10 May 2026\\", \\"current\\": \\"10 May 2026 - 09 Jun 2026\\" },\\n    \\"statistics\\": {\\n      \\"tax_collected\\": {\\n        \\"previous\\": 2724.35,\\n        \\"current\\": 969.75,\\n        \\"formatted_total\\": \\"$969.75\\",\\n        \\"progress\\": -64.4\\n      },\\n      \\"top_categories\\": [\\n        { \\"id\\": 1, \\"tax_category_id\\": 1, \\"name\\": \\"Standard Rate\\", \\"total\\": 712.4, \\"progress\\": 14.2, \\"formatted_total\\": \\"$712.40\\" },\\n        { \\"id\\": 2, \\"tax_category_id\\": 2, \\"name\\": \\"Reduced Rate\\", \\"total\\": 257.35, \\"progress\\": -5.6, \\"formatted_total\\": \\"$257.35\\" }\\n      ],\\n      \\"over_time\\": {\\n        \\"previous\\": [\\n          { \\"label\\": \\"10 Apr\\", \\"total\\": 420, \\"count\\": 6 },\\n          { \\"label\\": \\"11 Apr\\", \\"total\\": 185.05, \\"count\\": 3 }\\n        ],\\n        \\"current\\": [\\n          { \\"label\\": \\"10 May\\", \\"total\\": 850, \\"count\\": 12 },\\n          { \\"label\\": \\"11 May\\", \\"total\\": 119.75, \\"count\\": 4 }\\n        ]\\n      }\\n    }\\n  }\\n]\\n"},{"id":"rest-sales-shipping-collected","title":"Shipping Collected","description":"Shipping charges collected for the window vs. the previous period, the top shipping methods by collected amount, and the previous/current over-time series.","query":"curl -X GET \\"https://your-domain.com/api/admin/reporting/sales?type=shipping-collected&start=2026-05-10&end=2026-06-09&channel=default\\" \\\\\\n  -H \\"Accept: application/json\\" \\\\\\n  -H \\"Authorization: Bearer <id>|<token>\\"\\n","response":"[\\n  {\\n    \\"entity\\": \\"sales\\",\\n    \\"type\\": \\"shipping-collected\\",\\n    \\"dateRange\\": { \\"previous\\": \\"10 Apr 2026 - 10 May 2026\\", \\"current\\": \\"10 May 2026 - 09 Jun 2026\\" },\\n    \\"statistics\\": {\\n      \\"shipping_collected\\": {\\n        \\"previous\\": 960,\\n        \\"current\\": 540,\\n        \\"formatted_total\\": \\"$540.00\\",\\n        \\"progress\\": -43.75\\n      },\\n      \\"top_methods\\": [\\n        { \\"id\\": \\"flatrate_flatrate\\", \\"title\\": \\"Flat Rate\\", \\"total\\": 420, \\"progress\\": 5.5, \\"formatted_total\\": \\"$420.00\\" },\\n        { \\"id\\": \\"free_free\\", \\"title\\": \\"Free Shipping\\", \\"total\\": 120, \\"progress\\": -12, \\"formatted_total\\": \\"$120.00\\" }\\n      ],\\n      \\"over_time\\": {\\n        \\"previous\\": [\\n          { \\"label\\": \\"10 Apr\\", \\"total\\": 180, \\"count\\": 6 },\\n          { \\"label\\": \\"11 Apr\\", \\"total\\": 90, \\"count\\": 3 }\\n        ],\\n        \\"current\\": [\\n          { \\"label\\": \\"10 May\\", \\"total\\": 360, \\"count\\": 12 },\\n          { \\"label\\": \\"11 May\\", \\"total\\": 60, \\"count\\": 4 }\\n        ]\\n      }\\n    }\\n  }\\n]\\n"},{"id":"rest-sales-top-payment-methods","title":"Top Payment Methods","description":"Payment methods ranked by collected amount. Here `statistics` is a flat array of method rows, not an object.","query":"curl -X GET \\"https://your-domain.com/api/admin/reporting/sales?type=top-payment-methods&start=2026-05-10&end=2026-06-09&channel=default\\" \\\\\\n  -H \\"Accept: application/json\\" \\\\\\n  -H \\"Authorization: Bearer <id>|<token>\\"\\n","response":"[\\n  {\\n    \\"entity\\": \\"sales\\",\\n    \\"type\\": \\"top-payment-methods\\",\\n    \\"dateRange\\": { \\"previous\\": \\"10 Apr 2026 - 10 May 2026\\", \\"current\\": \\"10 May 2026 - 09 Jun 2026\\" },\\n    \\"statistics\\": [\\n      {\\n        \\"id\\": 1,\\n        \\"method\\": \\"cashondelivery\\",\\n        \\"method_title\\": \\"Cash On Delivery\\",\\n        \\"title\\": \\"Cash On Delivery\\",\\n        \\"total\\": 6420.5,\\n        \\"base_total\\": 6420.5,\\n        \\"progress\\": 18.4,\\n        \\"formatted_total\\": \\"$6,420.50\\"\\n      },\\n      {\\n        \\"id\\": 2,\\n        \\"method\\": \\"moneytransfer\\",\\n        \\"method_title\\": \\"Money Transfer\\",\\n        \\"title\\": \\"Money Transfer\\",\\n        \\"total\\": 3277.03,\\n        \\"base_total\\": 3277.03,\\n        \\"progress\\": -9.2,\\n        \\"formatted_total\\": \\"$3,277.03\\"\\n      }\\n    ]\\n  }\\n]\\n"},{"id":"rest-sales-sales-by-coupon","title":"Sales By Coupon","description":"Top coupon codes by discount given. Here `statistics` is a flat array of coupon rows, not an object.","query":"curl -X GET \\"https://your-domain.com/api/admin/reporting/sales?type=sales-by-coupon&start=2026-05-10&end=2026-06-09&channel=default\\" \\\\\\n  -H \\"Accept: application/json\\" \\\\\\n  -H \\"Authorization: Bearer <id>|<token>\\"\\n","response":"[\\n  {\\n    \\"entity\\": \\"sales\\",\\n    \\"type\\": \\"sales-by-coupon\\",\\n    \\"dateRange\\": { \\"previous\\": \\"07 May 2026 - 06 Jun 2026\\", \\"current\\": \\"06 Jun 2026 - 06 Jul 2026\\" },\\n    \\"statistics\\": [\\n      {\\n        \\"coupon_code\\": \\"SAVE10\\",\\n        \\"cart_rule_id\\": 1,\\n        \\"total\\": 12,\\n        \\"base_total\\": \\"2480.0000\\",\\n        \\"base_discount_total\\": \\"248.0000\\",\\n        \\"formatted_total\\": \\"$2,480.00\\",\\n        \\"formatted_discount_total\\": \\"$248.00\\",\\n        \\"link\\": \\"https://your-domain.com/admin/marketing/promotions/cart-rules/edit/1\\",\\n        \\"progress\\": 42.5,\\n        \\"datetime\\": null\\n      }\\n    ]\\n  }\\n]\\n"},{"id":"rest-sales-view","title":"View Details (table form)","description":"The expanded, row-by-row table behind a panel\'s \\"View Details\\" link. `statistics` carries ordered `columns` plus the full `records` list — the same shape for every `type`.","query":"curl -X GET \\"https://your-domain.com/api/admin/reporting/sales/view?type=total-sales&start=2026-05-10&end=2026-06-09&channel=default\\" \\\\\\n  -H \\"Accept: application/json\\" \\\\\\n  -H \\"Authorization: Bearer <id>|<token>\\"\\n","response":"[\\n  {\\n    \\"entity\\": \\"sales\\",\\n    \\"type\\": \\"total-sales\\",\\n    \\"dateRange\\": { \\"previous\\": \\"10 Apr 2026 - 10 May 2026\\", \\"current\\": \\"10 May 2026 - 09 Jun 2026\\" },\\n    \\"statistics\\": {\\n      \\"columns\\": [\\n        { \\"key\\": \\"label\\", \\"label\\": \\"Date\\" },\\n        { \\"key\\": \\"count\\", \\"label\\": \\"Orders\\" },\\n        { \\"key\\": \\"formatted_total\\", \\"label\\": \\"Total\\" }\\n      ],\\n      \\"records\\": [\\n        { \\"label\\": \\"10 May\\", \\"total\\": 8500, \\"count\\": 12, \\"formatted_total\\": \\"$8,500.00\\" },\\n        { \\"label\\": \\"11 May\\", \\"total\\": 1197.53, \\"count\\": 4, \\"formatted_total\\": \\"$1,197.53\\" }\\n      ]\\n    }\\n  }\\n]\\n"},{"id":"rest-sales-export","title":"Export (CSV)","description":"The detailed table streamed as a text/csv attachment (the \\"Export\\" button). The header row is built from the column labels, followed by one line per record.","query":"curl -X GET \\"https://your-domain.com/api/admin/reporting/sales/export?type=total-sales&format=csv&start=2026-05-10&end=2026-06-09&channel=default\\" \\\\\\n  -H \\"Authorization: Bearer <id>|<token>\\" \\\\\\n  -H \\"Accept: text/csv\\" \\\\\\n  -o sales-report.csv\\n","response":"Date,Orders,Total\\n10 May,12,\\"$8,500.00\\"\\n11 May,4,\\"$1,197.53\\"\\n"},{"id":"rest-sales-export-xlsx","title":"Export (XLSX)","description":"The detailed table streamed as an XLSX workbook (the \\"Export\\" button). The header row is built from the column labels, followed by one line per record.","query":"curl -X GET \\"https://your-domain.com/api/admin/reporting/sales/export?type=total-sales&format=xlsx&start=2026-05-10&end=2026-06-09&channel=default\\" \\\\\\n  -H \\"Authorization: Bearer <id>|<token>\\" \\\\\\n  -H \\"Accept: application/vnd.openxmlformats-officedocument.spreadsheetml.sheet\\" \\\\\\n  -o sales-report.xlsx\\n","response":"# Binary response: an XLSX workbook is written to disk\\n# (Content-Type: application/vnd.openxmlformats-officedocument.spreadsheetml.sheet\\n#  Content-Disposition: attachment; filename=\\"sales-<type>.xlsx\\").\\n# Same columns as the CSV export, as the first sheet\'s header row plus one row per record.\\n"}]},"headers":[],"relativePath":"api/rest-api/admin/reporting/sales.md","filePath":"api/rest-api/admin/reporting/sales.md","lastUpdated":1784902076000}'),n={name:"api/rest-api/admin/reporting/sales.md"};function d(s,e,c,i,l,p){return a(),o("div",null,e[0]||(e[0]=[r('<h1 id="reporting-—-sales" tabindex="-1">Reporting — Sales <a class="header-anchor" href="#reporting-—-sales" aria-label="Permalink to &quot;Reporting — Sales&quot;">​</a></h1><p>Returns the aggregate statistics that power the Bagisto admin <strong>Reporting → Sales</strong> screen — total sales, average order value, order counts, the purchase funnel, abandoned carts, refunds, tax and shipping collected, and the top payment methods.</p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>Stats endpoint</strong></td><td><code>GET /api/admin/reporting/sales</code></td></tr><tr><td><strong>View Details endpoint</strong></td><td><code>GET /api/admin/reporting/sales/view</code></td></tr><tr><td><strong>Export endpoint</strong></td><td><code>GET /api/admin/reporting/sales/export</code></td></tr><tr><td><strong>Returns</strong></td><td>A JSON <strong>array</strong> with a single element: <code>[ { entity, type, dateRange, statistics } ]</code></td></tr></tbody></table><p>All admin endpoints require an admin Bearer token — see <a href="/api/rest-api/admin/authentication.html">Authentication</a>. Reporting has <strong>no permission gate</strong>; any authenticated admin can read it.</p><h2 id="understanding-type-—-the-sales-report-is-ten-separate-calls" tabindex="-1">Understanding <code>type</code> — the Sales report is <strong>ten</strong> separate calls <a class="header-anchor" href="#understanding-type-—-the-sales-report-is-ten-separate-calls" aria-label="Permalink to &quot;Understanding `type` — the Sales report is **ten** separate calls&quot;">​</a></h2><p>This is the most important thing to understand about this API.</p><p>The Bagisto admin Sales report is <strong>not one response</strong>. The page is assembled from <strong>ten independent requests</strong>, one per panel, and each is selected with the <code>?type=</code> query parameter. These ten groups are exactly the panels of the admin Sales report screen — no more, no less.</p><p>So a single call returns <strong>one panel</strong> of the report. To render the full screen, call the endpoint once per <code>type</code> (or only for the panels you need). The <code>statistics</code> payload <strong>changes shape per <code>type</code></strong> — sometimes an object, sometimes a flat array — so always branch on <code>type</code> when consuming it.</p><h3 id="which-type-maps-to-which-panel" tabindex="-1">Which <code>type</code> maps to which panel <a class="header-anchor" href="#which-type-maps-to-which-panel" aria-label="Permalink to &quot;Which `type` maps to which panel&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Sales report panel (admin)</th><th><code>type</code></th><th><code>statistics</code> is</th></tr></thead><tbody><tr><td><strong>Total Sales</strong> chart</td><td><code>total-sales</code></td><td>object (with <code>over_time</code> series)</td></tr><tr><td><strong>Average Sales</strong> chart</td><td><code>average-sales</code></td><td>object (with <code>over_time</code> series)</td></tr><tr><td><strong>Total Orders</strong> chart</td><td><code>total-orders</code></td><td>object (with <code>over_time</code> series)</td></tr><tr><td><strong>Purchase Funnel</strong></td><td><code>purchase-funnel</code></td><td>object (no series; chart-only)</td></tr><tr><td><strong>Abandoned Carts</strong></td><td><code>abandoned-carts</code></td><td>object (with a <code>products</code> list)</td></tr><tr><td><strong>Refunds</strong> chart</td><td><code>refunds</code></td><td>object (with <code>over_time</code> series)</td></tr><tr><td><strong>Tax Collected</strong></td><td><code>tax-collected</code></td><td>object (with <code>top_categories</code> + <code>over_time</code>)</td></tr><tr><td><strong>Shipping Collected</strong></td><td><code>shipping-collected</code></td><td>object (with <code>top_methods</code> + <code>over_time</code>)</td></tr><tr><td><strong>Top Payment Methods</strong></td><td><code>top-payment-methods</code></td><td>array</td></tr><tr><td><strong>Sales By Coupon</strong></td><td><code>sales-by-coupon</code></td><td>array</td></tr></tbody></table><p><code>total-sales</code> is the default — if you omit <code>?type=</code>, you get the &quot;Total Sales&quot; panel.</p><h2 id="query-parameters" tabindex="-1">Query parameters <a class="header-anchor" href="#query-parameters" aria-label="Permalink to &quot;Query parameters&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Param</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>type</code></td><td>enum</td><td>No</td><td>One of the ten values above. Defaults to <code>total-sales</code>.</td></tr><tr><td><code>start</code></td><td>date (YYYY-MM-DD)</td><td>No</td><td>Lower bound of the reporting window. Defaults to <strong>30 days ago</strong>.</td></tr><tr><td><code>end</code></td><td>date (YYYY-MM-DD)</td><td>No</td><td>Upper bound. Defaults to <strong>today</strong>.</td></tr><tr><td><code>channel</code></td><td>string</td><td>No</td><td>Channel <strong>code</strong> to scope the figures to a single channel. Defaults to all channels.</td></tr></tbody></table><p><code>start</code> / <code>end</code> drive both the current figures and the <code>previous</code> baseline used for each <code>progress</code> percentage — the previous period is the same-length window immediately before <code>start</code>.</p><h2 id="response-envelope" tabindex="-1">Response envelope <a class="header-anchor" href="#response-envelope" aria-label="Permalink to &quot;Response envelope&quot;">​</a></h2><p>The endpoint always returns a <strong>single-element array</strong>: <code>[ { entity, type, dateRange, statistics } ]</code>.</p><ul><li><code>entity</code> — always <code>&quot;sales&quot;</code> for this endpoint.</li><li><code>type</code> — echoes back the requested panel.</li><li><code>dateRange</code> — an <strong>object</strong> <code>{ previous, current }</code> with a human-readable label for each window (e.g. <code>&quot;10 May 2026 - 09 Jun 2026&quot;</code>).</li><li><code>statistics</code> — an object or array whose shape depends on <code>type</code> (documented below).</li></ul><h2 id="response-shapes-by-type" tabindex="-1">Response shapes by <code>type</code> <a class="header-anchor" href="#response-shapes-by-type" aria-label="Permalink to &quot;Response shapes by `type`&quot;">​</a></h2><p>Figures with a <code>previous</code> / <code>current</code> / <code>progress</code> shape are period comparisons: <code>current</code> is the chosen window, <code>previous</code> is the preceding window of equal length, and <code>progress</code> is the percentage change (can be negative). The <code>over_time</code> series is split into a <code>previous</code> and a <code>current</code> array, each carrying one bucket per day with <code>{ label, total, count }</code>.</p><h3 id="total-sales" tabindex="-1"><code>total-sales</code> <a class="header-anchor" href="#total-sales" aria-label="Permalink to &quot;`total-sales`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Key</th><th>Shape</th><th>Meaning</th></tr></thead><tbody><tr><td><code>sales</code></td><td><code>{ previous, current, formatted_total, progress }</code></td><td>Gross sales for the window.</td></tr><tr><td><code>over_time</code></td><td><code>{ previous: [{ label, total, count }], current: [...] }</code></td><td>Per-day series for the chart. <code>total</code> is sales, <code>count</code> is order count.</td></tr></tbody></table><h3 id="average-sales" tabindex="-1"><code>average-sales</code> <a class="header-anchor" href="#average-sales" aria-label="Permalink to &quot;`average-sales`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Key</th><th>Shape</th><th>Meaning</th></tr></thead><tbody><tr><td><code>sales</code></td><td><code>{ previous, current, formatted_total, progress }</code></td><td>Average order value for the window.</td></tr><tr><td><code>over_time</code></td><td><code>{ previous: [{ label, total, count }], current: [...] }</code></td><td>Per-day series for the chart.</td></tr></tbody></table><h3 id="total-orders" tabindex="-1"><code>total-orders</code> <a class="header-anchor" href="#total-orders" aria-label="Permalink to &quot;`total-orders`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Key</th><th>Shape</th><th>Meaning</th></tr></thead><tbody><tr><td><code>orders</code></td><td><code>{ previous, current, progress }</code></td><td>Order count for the window (no <code>formatted_total</code>).</td></tr><tr><td><code>over_time</code></td><td><code>{ previous: [{ label, total, count }], current: [...] }</code></td><td>Per-day series for the chart.</td></tr></tbody></table><h3 id="purchase-funnel" tabindex="-1"><code>purchase-funnel</code> <a class="header-anchor" href="#purchase-funnel" aria-label="Permalink to &quot;`purchase-funnel`&quot;">​</a></h3><p>Object only — <strong>no over-time series and no table (<code>/view</code>) form</strong>.</p><table tabindex="0"><thead><tr><th>Key</th><th>Shape</th><th>Meaning</th></tr></thead><tbody><tr><td><code>visitors</code></td><td><code>{ total, progress }</code></td><td>Store visitors.</td></tr><tr><td><code>product_visitors</code></td><td><code>{ total, progress }</code></td><td>Visitors who viewed a product.</td></tr><tr><td><code>carts</code></td><td><code>{ total, progress }</code></td><td>Carts created.</td></tr><tr><td><code>orders</code></td><td><code>{ total, progress }</code></td><td>Orders placed.</td></tr></tbody></table><p>Each stage carries a single running <code>total</code> plus <code>progress</code> — there is no <code>previous</code> / <code>current</code> split here.</p><h3 id="abandoned-carts" tabindex="-1"><code>abandoned-carts</code> <a class="header-anchor" href="#abandoned-carts" aria-label="Permalink to &quot;`abandoned-carts`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Key</th><th>Shape</th><th>Meaning</th></tr></thead><tbody><tr><td><code>sales</code></td><td><code>{ previous, current, formatted_total, progress }</code></td><td>Value left in abandoned carts.</td></tr><tr><td><code>carts</code></td><td><code>{ previous, current, progress }</code></td><td>Abandoned-cart count.</td></tr><tr><td><code>rate</code></td><td><code>{ previous, current, progress }</code></td><td>Abandonment rate (percent).</td></tr><tr><td><code>products</code></td><td><code>array</code> of <code>{ id, name, count, progress }</code></td><td>Products most often left in abandoned carts.</td></tr></tbody></table><h3 id="refunds" tabindex="-1"><code>refunds</code> <a class="header-anchor" href="#refunds" aria-label="Permalink to &quot;`refunds`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Key</th><th>Shape</th><th>Meaning</th></tr></thead><tbody><tr><td><code>refunds</code></td><td><code>{ previous, current, formatted_total, progress }</code></td><td>Refunded amount for the window.</td></tr><tr><td><code>over_time</code></td><td><code>{ previous: [{ label, total, count }], current: [...] }</code></td><td>Per-day series for the chart.</td></tr></tbody></table><h3 id="tax-collected" tabindex="-1"><code>tax-collected</code> <a class="header-anchor" href="#tax-collected" aria-label="Permalink to &quot;`tax-collected`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Key</th><th>Shape</th><th>Meaning</th></tr></thead><tbody><tr><td><code>tax_collected</code></td><td><code>{ previous, current, formatted_total, progress }</code></td><td>Tax collected for the window.</td></tr><tr><td><code>top_categories</code></td><td><code>array</code> of <code>{ id, tax_category_id, name, total, progress, formatted_total }</code></td><td>Tax categories ranked by collected amount.</td></tr><tr><td><code>over_time</code></td><td><code>{ previous: [{ label, total, count }], current: [...] }</code></td><td>Per-day series for the chart.</td></tr></tbody></table><h3 id="shipping-collected" tabindex="-1"><code>shipping-collected</code> <a class="header-anchor" href="#shipping-collected" aria-label="Permalink to &quot;`shipping-collected`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Key</th><th>Shape</th><th>Meaning</th></tr></thead><tbody><tr><td><code>shipping_collected</code></td><td><code>{ previous, current, formatted_total, progress }</code></td><td>Shipping charges collected for the window.</td></tr><tr><td><code>top_methods</code></td><td><code>array</code> of <code>{ id, title, total, progress, formatted_total }</code></td><td>Shipping methods ranked by collected amount.</td></tr><tr><td><code>over_time</code></td><td><code>{ previous: [{ label, total, count }], current: [...] }</code></td><td>Per-day series for the chart.</td></tr></tbody></table><h3 id="top-payment-methods" tabindex="-1"><code>top-payment-methods</code> <a class="header-anchor" href="#top-payment-methods" aria-label="Permalink to &quot;`top-payment-methods`&quot;">​</a></h3><p><code>statistics</code> is an <strong>array</strong> (one row per payment method, ranked by collected amount). Each row: <code>id</code>, <code>method</code>, <code>method_title</code>, <code>title</code>, <code>total</code>, <code>base_total</code>, <code>progress</code>, <code>formatted_total</code>.</p><h3 id="sales-by-coupon" tabindex="-1"><code>sales-by-coupon</code> <a class="header-anchor" href="#sales-by-coupon" aria-label="Permalink to &quot;`sales-by-coupon`&quot;">​</a></h3><p><code>statistics</code> is an <strong>array</strong> (one row per coupon code used, ranked by discount given). Each row: <code>coupon_code</code>, <code>cart_rule_id</code>, <code>total</code> (orders using the coupon), <code>base_total</code>, <code>base_discount_total</code>, <code>formatted_total</code>, <code>formatted_discount_total</code>, <code>link</code> (admin cart-rule edit URL, <code>null</code> if the rule was deleted), <code>progress</code>, <code>datetime</code>.</p><h2 id="view-details" tabindex="-1">View Details <a class="header-anchor" href="#view-details" aria-label="Permalink to &quot;View Details&quot;">​</a></h2><p><code>GET /api/admin/reporting/sales/view</code> returns the same statistics as the summary stats endpoint, but in a detailed table form — the full list that sits behind a panel&#39;s <strong>View Details</strong> link. The <code>statistics</code> object carries:</p><ul><li><code>columns</code> — an ordered list of <code>{ key, label }</code> describing each table column.</li><li><code>records</code> — the row data, each keyed by the column <code>key</code> values.</li></ul><p>The table shape is <strong>uniform across every <code>type</code></strong> (<code>columns</code> + <code>records</code>); only the column set and row keys change. It honors the same <code>type</code>, <code>start</code>, <code>end</code> and <code>channel</code> parameters as the stats endpoint. (The <code>purchase-funnel</code> type is chart-only and has no table form.)</p><h2 id="export-csv" tabindex="-1">Export (CSV) <a class="header-anchor" href="#export-csv" aria-label="Permalink to &quot;Export (CSV)&quot;">​</a></h2><p><code>GET /api/admin/reporting/sales/export</code> streams the same detailed table as a csv, xls or xlsx attachment (the <strong>Export</strong> button). The header row is built from the column labels, followed by one line per record. Send the <code>Accept</code> header matching the requested format and save the response to a file. It honors the same <code>type</code>, <code>start</code>, <code>end</code> and <code>channel</code> parameters.</p><p><code>?format=</code> accepts <code>csv</code> (the default), <code>xls</code> and <code>xlsx</code> — any other value returns HTTP <strong>422</strong>. Send an <code>Accept</code> header matching the format: <code>text/csv</code>, <code>application/vnd.ms-excel</code> or <code>application/vnd.openxmlformats-officedocument.spreadsheetml.sheet</code>.</p><h2 id="errors" tabindex="-1">Errors <a class="header-anchor" href="#errors" aria-label="Permalink to &quot;Errors&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Condition</th><th>HTTP</th><th>Body</th></tr></thead><tbody><tr><td>Missing / invalid Bearer token</td><td><code>401</code></td><td><code>{ &quot;message&quot;: &quot;Unauthenticated.&quot;, &quot;error&quot;: &quot;unauthenticated&quot; }</code></td></tr><tr><td>Unsupported <code>format</code> on export</td><td><code>422</code></td><td><code>{ ... &quot;Unsupported export format.&quot; }</code></td></tr></tbody></table><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="/api/graphql-api/admin/reporting/sales.html">Reporting — Sales (GraphQL)</a> — same data over the <code>statsAdminReportingSales</code> query.</li><li><a href="/api/rest-api/admin/reporting/">Reporting Overview</a> — the customer and product report endpoints.</li></ul>',52)]))}const m=t(n,[["render",d]]);export{u as __pageData,m as default};
